.user-menu { display: flex; align-items: center; gap: 8px; min-height: 36px; }.user-menu__sign-in { display: inline-flex; align-items: center; gap: 6px; padding: 8px 18px; background: var(--color-primary); color: var(--text-on-accent, #fafafa); border: none; border-radius: var(--radius-pill); font-size: 14px; font-weight: 600; transition: background-color 0.2s ease 0s; }.user-menu__sign-in:hover:not(:disabled) { background: var(--color-primary-hover); }.user-menu__sign-in:disabled { opacity: 0.85; cursor: wait; }.user-menu__container { position: relative; }.user-menu__trigger { display: flex; align-items: center; gap: 8px; padding: 4px 8px; background: none; border: none; border-radius: var(--radius); transition: background-color 0.15s ease 0s; }.user-menu__trigger:hover { background: var(--color-surface-hover); }.user-menu__avatar { width: 28px; height: 28px; border-radius: 50%; object-fit: cover; }.user-menu__avatar-fallback { width: 28px; height: 28px; border-radius: 50%; background: var(--color-primary); color: var(--text-on-accent, #fafafa); display: flex; align-items: center; justify-content: center; font-size: 12px; font-weight: 600; }.user-menu__name { font-size: 14px; font-weight: 500; color: var(--color-text-primary); }.user-menu__dropdown { position: absolute; top: 100%; right: 0px; margin-top: 4px; background: var(--color-surface); border: 1px solid var(--color-border); border-radius: var(--radius-lg); box-shadow: var(--shadow-float); min-width: 180px; z-index: 100; padding: 4px; }.user-menu__dropdown-info { padding: 8px 12px; border-bottom: 1px solid var(--color-border-light); margin-bottom: 4px; }.user-menu__dropdown-name { font-size: 14px; font-weight: 600; color: var(--color-text-primary); }.user-menu__dropdown-email { font-size: 12px; color: var(--color-text-muted); margin-top: 2px; }.user-menu__dropdown-item { display: flex; align-items: center; gap: 8px; width: 100%; padding: 8px 12px; font-size: 14px; color: var(--color-text-secondary); background: none; border: none; border-radius: 6px; text-decoration: none; transition: background-color 0.15s ease 0s; }.user-menu__dropdown-item:hover:not(:disabled) { background: var(--color-surface-hover); color: var(--color-text-primary); }.user-menu__dropdown-item:disabled { opacity: 0.7; cursor: wait; }.user-menu__spinner { animation: 1s linear 0s infinite normal none running user-menu-spin; }@keyframes user-menu-spin { 
